type Spec<T> = (candidate: T) => boolean;
const and = <T>(...rules: Spec<T>[]): Spec<T> => (c) => rules.every((r) => r(c));

const isPaid = (i: Invoice): i is PaidInvoice => i.paidAt !== null;
const overdue: Spec<Invoice> = (i) => Date.now() - i.dueDate > 30 * 864e5;

const collectable = and<Invoice>(overdue, (i) => !i.inCollection);
const paid: PaidInvoice[] = invoices.filter(isPaid);
